// ios/ShareExtension/ShareViewController.swift
import UIKit
import Social
import Flutter

class ShareViewController: SLComposeServiceViewController {
    private let channelName = "com.example.facebook_save/share"
    private var flutterEngine: FlutterEngine?

    override func viewDidLoad() {
        super.viewDidLoad()
        // Initialise a separate Flutter engine for the extension
        flutterEngine = FlutterEngine(name: "share_engine")
        flutterEngine?.run()
        // Register plugins (if any) – generated by Flutter tooling
        GeneratedPluginRegistrant.register(with: flutterEngine!)
    }

    // MARK: - SLComposeServiceViewController overrides
    override func isContentValid() -> Bool {
        // Here you could validate the content; we accept everything.
        return true
    }

    override func didSelectPost() {
        // Gather the shared items.
        var data = [String: Any]()
        if let extensionItem = extensionContext?.inputItems.first as? NSExtensionItem {
            // Text (if any)
            if let text = extensionItem.userInfo?["public.text"] as? String {
                data["text"] = text
            }
            // Attachments (images, videos, URLs)
            for provider in extensionItem.attachments ?? [] {
                // URL
                if provider.hasItemConformingToTypeIdentifier("public.url") {
                    provider.loadItem(forTypeIdentifier: "public.url", options: nil) { (item, error) in
                        if let url = item as? URL {
                            data["url"] = url.absoluteString
                        }
                    }
                }
                // Image
                else if provider.hasItemConformingToTypeIdentifier("public.image") {
                    provider.loadItem(forTypeIdentifier: "public.image", options: nil) { (item, error) in
                        if let url = item as? URL {
                            data["imageUri"] = url.path
                        }
                    }
                }
                // Video (common UTType for movie)
                else if provider.hasItemConformingToTypeIdentifier("public.movie") {
                    provider.loadItem(forTypeIdentifier: "public.movie", options: nil) { (item, error) in
                        if let url = item as? URL {
                            data["videoUri"] = url.path
                        }
                    }
                }
            }
        }
        // Send the data to Dart via MethodChannel
        if let engine = flutterEngine {
            let channel = FlutterMethodChannel(name: channelName, binaryMessenger: engine.binaryMessenger)
            channel.invokeMethod("onShare", arguments: data)
        }
        // Close the share extension UI
        self.extensionContext?.completeRequest(returningItems: [], completionHandler: nil)
    }

    override func configurationItems() -> [Any] {
        // No custom configuration UI needed.
        return []
    }
}
